  .hero h1 {
    font-size: calc(3.2rem * var(--heading-scale));
  }
  .sample-body > div {
    padding: 16px;
  }
  .dashboard-heading {
    align-items: start;
    flex-direction: column;
  }
  .metric-cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
