@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
  .card-interactive:hover,
  .factory-preview[data-card="interactive"] .ui-card:hover {
    transform: none;
  }
}
[data-motion="no-motion"] *,
[data-motion="no-motion"] *::before,
[data-motion="no-motion"] *::after {
  animation: none !important;
  transition: none !important;
  scroll-behavior: auto !important;
}

html:has([data-motion="no-motion"]) {
  scroll-behavior: auto;
}
[data-motion="no-motion"] .card-interactive:hover,
[data-motion="no-motion"][data-card="interactive"] .ui-card:hover {
  transform: none;
}
.ui-accordion [role="region"] {
  overflow: hidden;
}
.ui-accordion [role="region"][data-state="open"] {
  animation: accordion-down var(--motion-duration) ease-out;
}
.ui-accordion [role="region"][data-state="closed"] {
  animation: accordion-up var(--motion-duration) ease-out;
}
@keyframes accordion-down {
  from {
    height: 0;
    opacity: 0;
  }
  to {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
}
@keyframes accordion-up {
  from {
    height: var(--radix-accordion-content-height);
    opacity: 1;
  }
  to {
    height: 0;
    opacity: 0;
  }
}

